ows":[{"sheet":"CN Working Sheet","row":96}]},{"code":"LB-A090","slug":"lb-a090-45ba6a8135ce","name":"Not Named","seed_file":"05-cn-bags-b.sql","source_rows":[{"sheet":"CN Working Sheet","row":97}]},{"code":"LB-8620","slug":"lb-8620-3be4a6428910","name":"Not Named","seed_file":"05-cn-bags-b.sql","source_rows":[{"sheet":"CN Working Sheet","row":98}]},{"code":"LB-88-218","slug":"lb-88-218-0de21f1108ce","name":"Not Named","seed_file":"05-cn-bags-b.sql","source_rows":[{"sheet":"CN Working Sheet","row":99}]},{"code":"LB-8568","slug":"lb-8568-3c2b5ca56d99","name":"Not Named","seed_file":"05-cn-bags-b.sql","source_rows":[{"sheet":"CN Working Sheet","row":100}]},{"code":"LB-8569","slug":"lb-8569-4f12809c0a19","name":"Not Named","seed_file":"05-cn-bags-b.sql","source_rows":[{"sheet":"CN Working Sheet","row":101}]}]$review$::jsonb)
    AS x(code text, slug text, name text, seed_file text, source_rows jsonb)
), candidates AS (
  SELECT s.*, p.id AS product_id, p.barcode AS stored_code, p.name AS stored_name,
    p.category AS stored_category, p.category_id, p.stock_tracking_mode,
    p.base_price AS stored_price_kes, p.slug AS stored_slug, p.active,
    p.publish_to_pos, p.is_website_published,
    count(p.id) OVER (PARTITION BY s.code) AS matches
  FROM seed s LEFT JOIN public.products p
    ON lower(regexp_replace(btrim(p.barcode), '[[:space:]]+', '', 'g')) =
       lower(regexp_replace(btrim(s.code), '[[:space:]]+', '', 'g'))
    OR p.slug = s.slug
)
SELECT c.*, cat.slug AS existing_category_slug, cat.parent_id,
  (SELECT jsonb_agg(jsonb_build_object('id',pc.id,'colour',pc.color_name,
      'stock',pc.stock_quantity,'sizes',coalesce((
        SELECT jsonb_agg(jsonb_build_object('id',ps.id,'size_system',ps.size_system,
          'size',ps.size_label,'stock',ps.stock_quantity,'archived',ps.archived) ORDER BY ps.id)
        FROM public.product_color_sizes ps WHERE ps.color_id=pc.id
      ),'[]'::jsonb),'image_count',(
        SELECT count(*) FROM public.product_images pi WHERE pi.color_id=pc.id
      )) ORDER BY pc.id)
   FROM public.product_colors pc WHERE pc.product_id=c.product_id) AS existing_variants,
  (SELECT count(*) FROM public.pos_sale_items h WHERE h.product_id=c.product_id) AS pos_sale_lines,
  (SELECT count(*) FROM public.pos_return_items h WHERE h.product_id=c.product_id) AS pos_return_lines,
  (SELECT count(*) FROM public.order_items h WHERE h.product_id=c.product_id) AS website_order_lines,
  (SELECT count(*) FROM public.stock_movements h WHERE h.product_id=c.product_id) AS stock_movements,
  (SELECT count(*) FROM public.pos_stock_adjustments h WHERE h.product_id=c.product_id) AS stock_adjustments,
  (SELECT coalesce(jsonb_agg(jsonb_build_object('workbook_sha256',l.workbook_sha256,
    'action',l.approved_product->>'action','application_id',l.application_id,
    'sheet',l.sheet_name,'row',l.source_row,'product_id',l.product_id)), '[]'::jsonb)
   FROM public.excel_catalogue_imports l WHERE l.product_id=c.product_id OR EXISTS (
      SELECT 1 FROM jsonb_to_recordset(c.source_rows) AS src(sheet text, row int)
      WHERE l.workbook_sha256='a299523b77936493abe5079d45a1687b6405ec75a4d0fcc3b0a832d54dc89aa5' AND l.sheet_name=src.sheet AND l.source_row=src.row
   )) AS ledger
FROM candidates c LEFT JOIN public.categories cat ON cat.id=c.category_id
ORDER BY c.seed_file,c.code,c.product_id;

ROLLBACK;
